package org.opensourcepingpong.competition.algorithm;
import java.util.*;
public final class RoundRobinScheduleGenerator {private RoundRobinScheduleGenerator(){} public record Pair<T>(T a,T b){} public static <T> List<List<Pair<T>>> generate(List<T> source){List<T> p=new ArrayList<>(source);if(p.size()<2)throw new IllegalArgumentException();if(p.size()%2==1)p.add(null);int n=p.size();List<List<Pair<T>>> rounds=new ArrayList<>();for(int r=0;r<n-1;r++){List<Pair<T>> round=new ArrayList<>();for(int i=0;i<n/2;i++){T a=p.get(i),b=p.get(n-1-i);if(a!=null&&b!=null)round.add(new Pair<>(a,b));}rounds.add(round);List<T> next=new ArrayList<>();next.add(p.get(0));next.add(p.get(n-1));next.addAll(p.subList(1,n-1));p=next;}return rounds;} }
